package com.ciaac.minecraft.minigames.checkpointparkour;
import static org.junit.jupiter.api.Assertions.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;
class ParkourSessionTest{@Test void checkpointsMustBeOrderedAndFinish(){var s=new ParkourSession(UUID.randomUUID(),new ParkourConfig("r1",2,Duration.ZERO,Duration.ofMinutes(1)));s.start(Instant.EPOCH,UUID.randomUUID());assertThrows(IllegalArgumentException.class,()->s.checkpoint(1,Instant.EPOCH,UUID.randomUUID()));s.checkpoint(0,Instant.EPOCH.plusSeconds(1),UUID.randomUUID());s.checkpoint(1,Instant.EPOCH.plusSeconds(2),UUID.randomUUID());assertTrue(s.result().orElseThrow().valid());}
 @Test void exactMaximumDurationIsExpiredForCheckpointAndTick(){var checkpoint=new ParkourSession(UUID.randomUUID(),new ParkourConfig("r1",1,Duration.ZERO,Duration.ofMinutes(1)));checkpoint.start(Instant.EPOCH,UUID.randomUUID());checkpoint.checkpoint(0,Instant.EPOCH.plus(Duration.ofMinutes(1)),UUID.randomUUID());assertFalse(checkpoint.result().orElseThrow().valid());
  var tick=new ParkourSession(UUID.randomUUID(),new ParkourConfig("r1",1,Duration.ZERO,Duration.ofMinutes(1)));tick.start(Instant.EPOCH,UUID.randomUUID());tick.tick(Instant.EPOCH.plus(Duration.ofMinutes(1)),UUID.randomUUID());assertFalse(tick.result().orElseThrow().valid());}}
